        {
            const string method = "PCA.fitRandomized";
            RequireBasicShape(in X, method);
            RequireTallShape(in X, method);

            int n = X.M_Rows;
            int p = X.N_Cols;
            RequireTopK(k, n, p, method);
            RequireModelShapeTopK(in model, p, k, method);

            Stats.colMean(in X, ref model.mean);

            var Xc = X.floatTempMat(n, p);
            float totalVariance = BuildWorkingCopy(in X, scaling, in model.mean, ref model.scale, ref Xc);

            var Uk = X.floatTempMat(n, k);
            info = SVD.randomized(in Xc, ref Uk, ref model.explainedVariance, ref model.components,
                                                k, oversample, powerIters, seed, maxIter);
            bool converged = info;

            if (converged)
                SingularValuesToVariances(ref model.explainedVariance, k, n);

            FinalizeModel(ref model, k, totalVariance, converged);
            return converged;
        }

        /// <summary>fitRandomized discarding the SVDInfo diagnostics.</summary>
        public static bool fitRandomized(in floatMxN X, ref floatPCAModel model, int k,
                                          PCAScaling scaling, int oversample, int powerIters, uint seed, int maxIter)
            => fitRandomized(in X, ref model, k, scaling, oversample, powerIters, seed, maxIter, out _);

        /// <summary>fitRandomized forwarding SVD.randomized's own defaults verbatim: oversample=10,
        /// powerIters=2, seed=0x9E3779B1u, maxIter=Consts.sweepBudget(l) (l = min(k+10, X.N_Cols)).</summary>
        public static bool fitRandomized(in floatMxN X, ref floatPCAModel model, int k, PCAScaling scaling, out SVDInfo info)
            => fitRandomized(in X, ref model, k, scaling, 10, 2, 0x9E3779B1u, Consts.sweepBudget(math.min(k + 10, X.N_Cols)), out info);

        /// <summary>fitRandomized forwarding SVD.randomized's own defaults, discarding the SVDInfo diagnostics.</summary>
        public static bool fitRandomized(in floatMxN X, ref floatPCAModel model, int k, PCAScaling scaling)
            => fitRandomized(in X, ref model, k, scaling, out _);

        /// <summary>fitRandomized with scaling = PCAScaling.Covariance.</summary>
        public static bool fitRandomized(in floatMxN X, ref floatPCAModel model, int k, out SVDInfo info)
            => fitRandomized(in X, ref model, k, PCAScaling.Covariance, out info);

        /// <summary>fitRandomized with scaling = PCAScaling.Covariance, discarding the SVDInfo diagnostics.</summary>
        public static bool fitRandomized(in floatMxN X, ref floatPCAModel model, int k)
            => fitRandomized(in X, ref model, k, PCAScaling.Covariance, out _);

        /// <summary>Validates inputs, allocates the model (p x k) standalone via <paramref
        /// name="allocator"/> (default Temp; caller owns disposal), then delegates to the
        /// ref-model overload. Guards fire before any allocation.</summary>
        public static floatPCAModel fitRandomized(in floatMxN X, int k, PCAScaling scaling, Allocator allocator = Allocator.Temp)
        {
            const string method = "PCA.fitRandomized";
            RequireBasicShape(in X, method);
            RequireTallShape(in X, method);

            int n = X.M_Rows;
            int p = X.N_Cols;
            RequireTopK(k, n, p, method);

            var model = new floatPCAModel(p, k, allocator);
            fitRandomized(in X, ref model, k, scaling, out _);
            return model;
        }

        /// <summary>fitRandomized (allocating, Allocator) with scaling = PCAScaling.Covariance.</summary>
        public static floatPCAModel fitRandomized(in floatMxN X, int k, Allocator allocator = Allocator.Temp)
            => fitRandomized(in X, k, PCAScaling.Covariance, allocator);

        // =====================================================================================
        // Projection
        // =====================================================================================

        /// <summary>
        /// Projects X onto the model's principal axes: scores[i,:] = ((X[i,:] - model.mean) /
        /// model.scale) . model.components. Zero-alloc except for one n_new x p temp scratch matrix.
        /// X.N_Cols must match the model's feature count (model.mean/scale.N and
        /// model.components.M_Rows); model.k must equal model.components.N_Cols (defends a
        /// hand-assembled or stale model); scores must be X.M_Rows x model.k.
        /// </summary>
        public static void transform(in floatMxN X, in floatPCAModel model, ref floatMxN scores)
        {
            const string method = "PCA.transform";
            int p = X.N_Cols;
            int nNew = X.M_Rows;

            if (model.mean.N != p || model.scale.N != p || model.components.M_Rows != p)
                throw new ArgumentException(method + ": model.mean/scale/components must match X.N_Cols (p)");
            if (model.k != model.components.N_Cols)
                throw new ArgumentException(method + ": model.k must equal model.components.N_Cols (stale model)");
            if (scores.M_Rows != nNew || scores.N_Cols != model.k)
                throw new ArgumentException(method + ": scores must be X.M_Rows x model.k");

            var Xs = X.floatTempMat(nNew, p);
            for (int r = 0; r < nNew; r++)
                for (int c = 0; c < p; c++)
                    Xs[r, c] = (X[r, c] - model.mean[c]) / model.scale[c];

            Blas.dot(in Xs, in model.components, ref scores);
        }

        /// <summary>Allocating transform (Allocator): allocates and returns a fresh X.M_Rows x
        /// model.k scores matrix via <paramref name="allocator"/> (default Temp; caller owns
        /// disposal).</summary>
        public static floatMxN transform(in floatMxN X, in floatPCAModel model, Allocator allocator = Allocator.Temp)
        {
            const string method = "PCA.transform";
            int p = X.N_Cols;

            if (model.mean.N != p || model.scale.N != p || model.components.M_Rows != p)
                throw new ArgumentException(method + ": model.mean/scale/components must match X.N_Cols (p)");
            if (model.k != model.components.N_Cols)
                throw new ArgumentException(method + ": model.k must equal model.components.N_Cols (stale model)");

            var scores = new floatMxN(X.M_Rows, model.k, allocator);
            transform(in X, in model, ref scores);
            return scores;
        }
    }
}
